function collectGenericInput(type){
 const panel=activeGenericPanel(type),schema=genericSchemas[type];if(!panel||!schema)throw new Error("请先成功加载采集参数 Schema");const input={};
 panel.querySelectorAll("[data-key]").forEach(el=>{const key=el.dataset.key,p=schema.properties[key];if(el.type==="checkbox"){input[key]=el.checked;return}const value=el.value.trim();if(!value)return;
  if(p.type==="number"||p.type==="integer")input[key]=Number(value);
  else if(p.type==="array"){try{const x=JSON.parse(value);input[key]=Array.isArray(x)?x:value.split(/\r?\n/).map(y=>y.trim()).filter(Boolean)}catch{input[key]=value.split(/\r?\n/).map(y=>y.trim()).filter(Boolean)}}
  else if(p.type==="object"){try{input[key]=JSON.parse(value)}catch{throw new Error(key+" 必须是有效 JSON 对象")}}
  else input[key]=value;
 });return input;
}
